    {R"(\[(?:(https?|ftp):\/\/)?([\w\-\.]+(:\d+)?)(\.\w+(\?\S*)?)\])", "<a href=\"$2$3\">$2$3</a>"}
};

std::string convertMarkdownToHtml(std::string& markdown) {
    std::string html;

    // Replace Markdown with HTML
    std::regex markdown_pattern(R"((?:[^\\n]+))");
    std::smatch markdown_match;
    std::string markdown_line;
    while (std::regex_search(markdown, markdown_match, markdown_pattern)) {
        markdown_line = markdown_match.str(1);
        std::string html_line;
        for (const auto& rule : MARKDOWN_TO_HTML) {
            std::string markdown_pattern_str(rule.first);
            std::string html_str(rule.second);
            std::regex markdown_regex(std::regex::icase, markdown_pattern_str);
